            // Need to show: spec.satisfied_by(ex) ==> always(p.implies(tla_forall(a_to_q))).satisfied_by(ex)
            assert(spec.satisfied_by(ex) ==> always(p.implies(tla_forall(a_to_q))).satisfied_by(ex)) by {
