                                            // The verifier should instantiate the universally-quantified precondition.
                                        };

                                        unfold TempPred::entails in Ha;
                                        unfold valid in Ha;
                                        // Ha is now: forall ex: Execution<T>, (spec.implies(always(p.implies(a_to_q(a))))).satisfied_by(ex)
                                        assert(spec.implies(always(p.implies(a_to_q(a)))).satisfied_by(ex)) by {
                                            // Instantiate Ha at the current execution ex.
                                            assert(forall |ex2: Execution<T>| spec.implies(always(p.implies(a_to_q(a)))).satisfied_by(ex2)) by {
                                                // Ha *is* that forall; unfold gives it.
                                            };
                                        };

                                        // From Ha instantiated at `ex`, we get:
                                        // spec.satisfied_by(ex) ==> always(p.implies(a_to_q(a))).satisfied_by(ex)
                                        // which we can use with our hypothesis `spec.satisfied_by(ex)`.
                                        assert(always(p.implies(a_to_q(a))).satisfied_by(ex)) by {
                                            unfold TempPred::implies;
                                            // Now `spec.implies(...).satisfied_by(ex)` is `spec.satisfied_by(ex) ==> ...`
                                            if spec.satisfied_by(ex) {
                                                // The implication holds; extract the consequent.
                                            }
                                        };

                                        // Now use `always` at index `i` to get `p.implies(a_to_q(a))).satisfied_by(es)`.
                                        assert(p.implies(a_to_q(a)).satisfied_by(es)) by {
                                            unfold always;
                                            // always(...) at ex gives the property for all indices.
                                            // Instantiate the forall at i.
                                        };

                                        // Finally, apply the implication with p.satisfied_by(es).
                                        unfold TempPred::implies;
                                        if p.satisfied_by(es) {
                                            // Goal: a_to_q(a).satisfied_by(es)
                                        }

                                        assert(a_to_q(a).satisfied_by(es));
                                    }
                                }

                                // If p.satisfied_by(es) is false, the implication holds trivially.
                                else {
                                    assert(tla_forall(a_to_q).satisfied_by(es) == false || true);
                                }
                            };
                        }
                    }
                }

                // If spec.satisfied_by(ex) is false, the implication holds trivially.
                else {
                    assert(always(p.implies(tla_forall(a_to_q))).satisfied_by(ex) == false || true);
                }
            }
        }
    }
}


